"use strict";
import styled from "lib/styled-components";
import { Body } from "pages/App/Body";
import { Header } from "pages/App/Header";
import { GRID_AREAS } from "pages/App/utils/shared";
import { useLocation } from "react-router-dom";
import { Flex, Silk } from "ui/src";
import { breakpoints } from "ui/src/theme";
const AppContainer = styled.div`
  min-height: 100vh;
  max-width: 100vw;

  // grid container settings
  display: grid;
  grid-template-columns: 1fr;
  grid-template-rows: auto auto 1fr;
  grid-template-areas: '${GRID_AREAS.HEADER}' '${GRID_AREAS.MAIN}' '${GRID_AREAS.MOBILE_BOTTOM_BAR}';
`;
const AppBody = styled.div`
  grid-area: ${GRID_AREAS.MAIN};
  width: 100vw;
  min-height: 100%;
  max-width: ${({ theme }) => `${theme.maxWidth}px`};
  display: flex;
  flex-direction: column;
  position: relative;
  align-items: center;
  flex: 1;
  position: relative;
  margin: auto;

  @media screen and (max-width: ${breakpoints.md}px) {
    padding-left: 10px;
    padding-right: 10px;
  }
`;
export function AppLayout() {
  const pathName = useLocation().pathname;
  const pathCheck = pathName === "/" || pathName === "/swap" || pathName === "/send";
  return <AppContainer>
      <Header />
      <AppBody>
        <Body />
      </AppBody>
      {pathCheck && <Flex opacity={0.08} zIndex={0} position="absolute" inset={0} width="100%" height="100%">
          <Silk speed={5} scale={1} color="#ffffffff" noiseIntensity={0.25} rotation={0} />
        </Flex>}
    </AppContainer>;
}
